332	func exchangeBearerTokenContext(ctx context.Context, challenge, username, password string) (string, error) {
333		params := parseBearerChallenge(challenge)
334		realm, ok := params["realm"]
335		if !ok {
336			return "", fmt.Errorf("bearer challenge missing realm")
337		}
338		u, err := url.Parse(realm)
339		if err != nil {
340			return "", fmt.Errorf("parse realm %q: %w", realm, err)
341		}
342		q := u.Query()
343		if s, ok := params["service"]; ok {
344			q.Set("service", s)
345		}
346		if s, ok := params["scope"]; ok {
347			q.Set("scope", s)
348		}
349		u.RawQuery = q.Encode()
350	
351		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
352		if err != nil {
353			return "", fmt.Errorf("build token request: %w", err)
354		}
355		if username != "" && password != "" {
356			req.SetBasicAuth(username, password)
357		}
358		resp, err := registryHTTPClient.Do(req)
359		if err != nil {
360			return "", fmt.Errorf("fetch token: %w", StripRedirectTarget(err))
361		}
362		defer func() { _ = resp.Body.Close() }()
363		if resp.StatusCode != http.StatusOK {
364			return "", &StatusError{Code: resp.StatusCode, Source: SourceToken}
365		}
366		body, err := io.ReadAll(io.LimitReader(resp.Body, maxTokenResponse+1))
367		if err != nil {
368			return "", fmt.Errorf("read token response: %w", err)
369		}
370		if len(body) > maxTokenResponse {
371			return "", fmt.Errorf("token response over %d bytes", maxTokenResponse)
372		}
373		var result struct {
374			Token       string `json:"token"`
375			AccessToken string `json:"access_token"`
376		}
377		if err := json.Unmarshal(body, &result); err != nil {
378			return "", fmt.Errorf("decode token response: %w", err)
379		}
380		if result.Token != "" {
381			return result.Token, nil
382		}
383		if result.AccessToken != "" {
384			return result.AccessToken, nil
385		}
386		return "", fmt.Errorf("token response contained no token field")
387	}
