389	// parseBearerChallenge parses the value portion of a Www-Authenticate: Bearer header.
390	// Example: `realm="https://auth.docker.io/token",service="registry.docker.io"`
391	func parseBearerChallenge(s string) map[string]string {
392		params := make(map[string]string)
393		for _, part := range strings.Split(s, ",") {
394			part = strings.TrimSpace(part)
395			idx := strings.IndexByte(part, '=')
396			if idx < 0 {
397				continue
398			}
399			key := strings.TrimSpace(part[:idx])
400			val := strings.Trim(strings.TrimSpace(part[idx+1:]), `"`)
401			params[key] = val
402		}
403		return params
404	}
